import {enablePageSwipe} from './swipe.js';
import {loginPage} from './login.js';
import {loadAcademy,chapters,discoverLessons} from './data.js';import {legacyAcademy} from './legacy-academy-data.js';import {legacyProfile} from './legacy-profile-data.js';import {resolveRoute} from './navigation.js';import {readPreferences,savePreferences} from './preferences.js';
let storage;try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}let preferences=readPreferences(storage);const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let state=await loadAcademy(window.StackUpAcademyAdapter);let previousFocus;
const nav=[['home','⌂','HOME'],['journey','▤','APRENDER'],['practice','♠','PRATICAR'],['evolution','↗','JOGAR'],['profile','♙','PERFIL']];
const heading=(tag,title,description)=>`<div class="page-heading"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${description}</p></div><span class="chapter-tag"></span></div>`;
const empty=(symbol,title,description)=>`<section class="empty"><div class="empty-symbol">${symbol}</div><h2>${title}</h2><p>${description}</p><a href="#journey" class="primary">EXPLORAR A JORNADA <span>→</span></a></section>`;
const nextApps=`<section class="next-apps"><div class="next-grid">${[['HEROES','Descubra seu Poker DNA.'],['GRINDER EVO','Decisões em Texas Hold’em.'],['REVOLUTION','Simulações de jogo.'],['D ACTION','Leaks no Omaha.'],['WRAPS','Decisões no Omaha.'],['CHIPS UP','Gestão de bankroll.']].map(([name,desc])=>`<button class="next-app" data-series="${name}"><strong>${name}</strong><span>${desc}</span><i>↗</i></button>`).join('')}</div></section>`;
const quote=`<div class="quote">“Poker é um jogo que demora minutos para aprender. Mas leva uma vida para dominar.”<small>— MIKE SEXTON</small></div>`;
const migratedList=(section,prefix,tag)=>heading(tag,section.title,section.description)+`<div class="list">${section.items.map((item,i)=>`<a class="chapter" href="#${prefix}/${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${String(item[0]).toUpperCase()}</h3><p>${item[1]}</p></div><span class="status">↗</span></a>`).join('')}</div>`;
const migratedDetail=(section,index,back,tag)=>{const item=section.items[index];if(!item)return empty('▤','Conteúdo não encontrado.','Volte para a etapa anterior e escolha outro conteúdo.');return `<a href="#${back}" class="back">← VOLTAR</a>`+heading(tag,String(item[0]).toUpperCase(),item[1])+`<section class="empty"><div class="empty-symbol">▤</div><h2>${String(item[0]).toUpperCase()}</h2><p>${item[1]}</p></section>`};
function openDialog(title,body){previousFocus=document.activeElement;document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').textContent=body;dialog.showModal()}
dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('#dialog-action').onclick=()=>dialog.close();dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function home(){return heading('ACADEMY · A PRIMEIRA DESCOBERTA','Aprenda. Pratique. Jogue.','Entenda o jogo, pratique o básico e chegue à mesa com segurança.')+`<section class="hero"><div class="pokerinno-logo" role="img" aria-label="POKERINNO ACADEMY"><svg viewBox="0 0 32 38" aria-hidden="true"><path d="M16 1C12 8 1 13 1 23c0 7 8 10 13 5l-3 9h10l-3-9c5 5 13 2 13-5C31 13 20 8 16 1Z"/></svg><div><strong>POKERINNO</strong><span>ACADEMY</span></div></div><img class="hero-image" src="assets/pokerino-hero.webp" alt="Pokerinno recebe você em uma academia de poker iluminada em dourado"><div class="hero-copy"><span class="eyebrow">SUA JORNADA · APRENDER → PRATICAR → JOGAR</span><h2>APRENDER.<br>PRATICAR.<br><em>JOGAR.</em></h2><p>“Poker é um jogo que demora minutos para aprender. Mas leva uma vida para dominar.”</p><small class="quote-author">— MIKE SEXTON</small><a href="#journey" class="primary">COMEÇAR A APRENDER <span>→</span></a></div><div class="hero-note">COM POKERINNO, CADA PASSO CONTA.</div></section><div class="section-top"><h2>ESCOLHA SUA AVENTURA</h2><span></span></div><div class="grid">${[['base','▤','SUA BASE','Fundamentos do jogo.'],['modalities','✧','MODALIDADES','Principais modalidades.'],['practice','♠','PRÁTICA','Decisões e treino.'],['evolution','↗','SUA EVOLUÇÃO','Progresso e evolução.']].map(([route,symbol,title,desc])=>`<a class="feature" href="#${route}"><span class="badge">${symbol}</span><span class="arrow">↗</span><h3>${title}</h3><p>${desc}</p></a>`).join('')}</div>`}
function render(){if(!location.hash||location.hash==='#login'){loginPage(app,'ACADEMY');return}document.body.classList.remove('login-screen');const route=resolveRoute(location.hash),active=(route.startsWith('chapter/')||route.startsWith('discover/')||route.startsWith('rule/')||route.startsWith('modality/'))?'journey':(route.startsWith('practice-tool/')?'practice':(route.startsWith('profile/')?'profile':route));for(const id of ['navigation','mobile-navigation'])document.getElementById(id).innerHTML=nav.map(([key,symbol,title])=>`<a class="${id==='navigation'?'nav-link ':''}${active===key?'active':''}" ${active===key?'aria-current="page"':''} href="#${key}"><span class="nav-symbol" aria-hidden="true">${symbol}</span>${title}</a>`).join('');document.documentElement.classList.toggle('reduced-motion',preferences.reducedMotion);
if(state.status==='error'){app.innerHTML=heading('SUA JORNADA','Vamos tentar novamente?','Sua navegação continua disponível.')+`<section class="empty"><h2>Não conseguimos carregar os conteúdos</h2><p>${state.error}</p><button class="primary" data-retry>TENTAR NOVAMENTE →</button></section>`;return}
if(route==='home')app.innerHTML=home();
else if(route==='journey')app.innerHTML=heading('PRIMEIRA AVENTURA','APRENDER','Aprenda o essencial para acompanhar o jogo e participar da mesa.')+`<div class="list">${chapters.map(c=>`<a class="chapter" href="#chapter/${c.id}"><span class="number">0${c.order}</span><div><h3>${String(c.title).toUpperCase()}</h3><p>${c.description}</p></div><span class="status">↗</span></a>`).join('')}</div>`;
else if(route==='chapter/rules'){const c=chapters.find(c=>c.id==='rules');app.innerHTML=`<a href="#journey" class="back back-journey">← VOLTAR À JORNADA</a>`+heading('CAPÍTULO 02',c.title,c.description)+`<div class="list">${legacyAcademy.base.items.map((item,i)=>`<a class="chapter" href="#rule/${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${String(item[0]).toUpperCase()}</h3><p>${item[1]}</p></div><span class="status">↗</span></a>`).join('')}</div>`}
else if(route.startsWith('rule/'))app.innerHTML=migratedDetail(legacyAcademy.base,Number(route.split('/')[1]),'chapter/rules','CONHECER AS REGRAS');
else if(route==='chapter/discover'){const c=chapters.find(c=>c.id==='discover');app.innerHTML=`<a href="#journey" class="back back-journey">← VOLTAR À JORNADA</a>`+heading(`CAPÍTULO 01`,c.title,c.description)+`<div class="list">${discoverLessons.map((lesson,i)=>`<a class="chapter" href="#discover/${lesson.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${lesson.title}</h3><p>${lesson.description}</p></div><span class="status">↗</span></a>`).join('')}</div>`}
else if(route.startsWith('discover/')){const lesson=discoverLessons.find(x=>x.id===route.split('/')[1]);app.innerHTML=`<a href="#chapter/discover" class="back back-journey">← VOLTAR À JORNADA</a>`+heading('DESCOBRIR O JOGO',lesson.title,lesson.description)+`<div class="list">${lesson.blocks.map(([title,body],i)=>`<section class="chapter lesson-block"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${body}</p></div></section>`).join('')}</div>`}
else if(route.startsWith('chapter/')){const c=chapters.find(c=>c.id===route.split('/')[1]);app.innerHTML=`<a href="#journey" class="back back-journey">← VOLTAR À JORNADA</a>`+heading(`CAPÍTULO 0${c.order}`,c.title,c.description)+empty('▤','Seu próximo capítulo está sendo preparado.','As aulas aparecerão aqui quando o conteúdo da jornada estiver disponível. Seu aprendizado começa com uma base bem construída.')+quote}
else if(route==='chapter/formats'){const c=chapters.find(c=>c.id==='formats');app.innerHTML=`<a href="#journey" class="back back-journey">← VOLTAR À JORNADA</a>`+heading('CAPÍTULO 04',c.title,c.description)+`<div class="list">${legacyAcademy.modalities.items.map((item,i)=>`<a class="chapter" href="#modality/${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${String(item[0]).toUpperCase()}</h3><p>${item[1]}</p></div><span class="status">↗</span></a>`).join('')}</div>`}
else if(route.startsWith('modality/'))app.innerHTML=migratedDetail(legacyAcademy.modalities,Number(route.split('/')[1]),'chapter/formats','EXPLORAR MODALIDADES');
else if(route==='practice')app.innerHTML=heading('DA DESCOBERTA À DECISÃO','Pratique o básico.','Entenda a dinâmica antes de enfrentar a mesa.')+`<div class="grid">${[['◷','TREINO RÁPIDO','Decisões básicas.','practice-tool/0'],['☷','TREINO PERSONALIZADO','Reforce seu aprendizado.','practice-tool/1'],['♜','DESAFIOS','Teste sua compreensão.','practice-tool/2'],['♠','REVISÃO DE MÃOS','Revise suas decisões.','practice-tool/1']].map(([s,t,d,target])=>`<button class="feature" data-practice-route="${target}"><span class="badge">${s}</span><span class="arrow">↗</span><h3>${String(t).toUpperCase()}</h3><p>${d}</p></button>`).join('')}</div>`+empty('♠','As primeiras decisões estão a caminho.','Quando os treinos estiverem disponíveis, você encontrará aqui seus desafios e a revisão das suas decisões.');
else if(route.startsWith('practice-tool/'))app.innerHTML=migratedDetail(legacyAcademy.practice,Number(route.split('/')[1]),'practice','PRATICAR');
else if(route==='evolution')app.innerHTML=heading('SUA HISTÓRIA','Sua preparação para a mesa.','Acompanhe os fundamentos que você está aprendendo.')+empty('↗','Sua história ainda vai começar.','Você ainda não possui aulas concluídas, treinos ou conquistas. O progresso aparecerá a partir das suas atividades reais.');
else if(route==='profile')app.innerHTML=heading('DO SEU JEITO','Seu espaço no Academy.','Pequenos ajustes para acompanhar a sua jornada.')+`<section class="empty"><div class="empty-symbol">♙</div><h2>Olá, explorador.</h2><p>Você está conhecendo o Academy. Conecte sua conta quando o acesso estiver disponível.</p><button class="primary" data-login>ACESSAR MINHA CONTA →</button></section><div class="section-top"><h2>EVOLUA COM POKERINNO</h2><span>PRÓXIMOS CAMINHOS</span></div>`+nextApps+`<div class="setting"><div><h3>Sons da jornada</h3><p>Preferência preparada para as experiências com áudio.</p></div><input type="checkbox" id="sound" aria-label="Sons da jornada" ${preferences.sound?'checked':''}></div><div class="setting"><div><h3>Reduzir movimentos</h3><p>Uma navegação mais tranquila, com menos animações.</p></div><input type="checkbox" id="reducedMotion" aria-label="Reduzir movimentos" ${preferences.reducedMotion?'checked':''}></div><div class="setting"><div><h3>Privacidade e conta</h3><p>Conta e sincronização disponíveis após a integração.</p></div><button class="quiet" data-login>CONSULTAR →</button></div><div class="section-top"><h2>CONFIGURAÇÕES DO ACADEMY</h2><span>PERFIL</span></div><div class="list">${legacyProfile.items.map(([key,title,desc],i)=>`<a class="chapter" href="#profile/${key}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${desc}</p></div><span class="status">↗</span></a>`).join('')}</div>`;
else if(route==='profile/access')app.innerHTML=`<a href="#profile" class="back">← VOLTAR</a>`+heading('PERFIL','DADOS DE ACESSO','Forma de acesso e dados da sessão atual.')+`<div class="setting"><div><h3>FORMA DE ACESSO</h3><p>Integração será conectada ao serviço de autenticação do app.</p></div></div><div class="setting"><div><h3>SESSÃO</h3><p>Acesso exploratório ativo enquanto a autenticação real não estiver conectada.</p></div></div>`;
else if(route==='profile/language')app.innerHTML=`<a href="#profile" class="back">← VOLTAR</a>`+heading('PERFIL','IDIOMA','Escolha o idioma do Academy.')+`<div class="entry-languages"><button data-profile-lang="pt-BR">PT-BR</button><button data-profile-lang="en-US">EN-US</button><button data-profile-lang="es-ES">ES-ES</button></div>`;
else if(route==='profile/history')app.innerHTML=`<a href="#profile" class="back">← VOLTAR</a>`+heading('PERFIL','SALVAMENTO DOS TREINOS','Controle como o histórico será armazenado.')+`<div class="setting"><div><h3>SALVAR TREINOS</h3><p>Preferência migrada do Academy anterior.</p></div><input type="checkbox" id="saveTraining" ${storage.getItem('academy.training.save')!=='off'?'checked':''}></div>`;
else if(route==='profile/plans')app.innerHTML=`<a href="#profile" class="back">← VOLTAR</a>`+heading('PERFIL','PLANOS','Estrutura de planos migrada do Academy anterior.')+`<div class="list">${legacyProfile.plans.map((p,i)=>`<div class="chapter"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${p.name}</h3><p>${p.price} ${p.period}</p></div></div>`).join('')}</div>`;
else if(route==='profile/coach')app.innerHTML=`<a href="#profile" class="back">← VOLTAR</a>`+heading('PERFIL','ACADEMY COACH','Configuração migrada para edição posterior.')+`<div class="setting"><div><h3>WHATSAPP</h3><p>Contato e consentimento serão reconectados nesta página.</p></div></div>`;
else if(route==='profile/privacy')app.innerHTML=`<a href="#profile" class="back">← VOLTAR</a>`+heading('PERFIL','SOBRE E PRIVACIDADE','Controles de privacidade e dados do Academy.')+`<div class="setting"><div><h3>POLÍTICA DE PRIVACIDADE</h3><p>Documento e ações de conta serão conectados aqui.</p></div></div><div class="setting"><div><h3>DADOS LOCAIS</h3><p>Limpeza de progresso, histórico e preferências será reconectada nesta página.</p></div></div>`;
else if(route==='welcome')app.innerHTML=home();
app.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.display='none'}));}
document.addEventListener('click',async e=>{const langBtn=e.target.closest('[data-profile-lang]');if(langBtn){try{localStorage.setItem('stackup.locale',langBtn.dataset.profileLang)}catch{}location.reload();return}const help=e.target.closest('[data-help]'),pending=e.target.closest('[data-pending]'),practiceRoute=e.target.closest('[data-practice-route]');const series=e.target.closest('[data-series]');if(series)openDialog(series.dataset.series,'Este é um dos próximos caminhos da série StackUp Hold’em. Cada app tem sua própria proposta. O acesso será conectado quando esse app estiver disponível nesta jornada.');if(help)openDialog('Oi! Eu sou o Pokerinno.','Vou ajudar você a entender o jogo, praticar o básico e chegar à mesa sabendo o que está acontecendo. O Academy prepara o iniciante; a especialização e a busca pelo domínio continuam nos demais apps da série StackUp Hold’em.');if(practiceRoute){location.hash=practiceRoute.dataset.practiceRoute;return}if(pending)openDialog(pending.dataset.pending,'Este espaço está pronto para receber os treinos. Assim que os desafios estiverem disponíveis, você poderá praticar por aqui.');if(e.target.closest('[data-login]'))location.hash='login';if(e.target.closest('[data-retry]')){state=await loadAcademy(window.StackUpAcademyAdapter);render()}});
document.addEventListener('change',e=>{if(e.target.id==='saveTraining'){try{storage.setItem('academy.training.save',e.target.checked?'on':'off')}catch{}}if(['sound','reducedMotion'].includes(e.target.id)){preferences[e.target.id]=e.target.checked;const saved=savePreferences(storage,preferences);document.documentElement.classList.toggle('reduced-motion',preferences.reducedMotion);if(!saved)openDialog('Preferência aplicada','Seu navegador não permitiu salvar este ajuste. Ele permanece ativo durante esta visita.')}});window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});render();

enablePageSwipe(nav.map(item=>item[0]));
